insert into catalog_topics (writing_type_id, level, title, prompt, min_words, max_words, estimated_minutes, tags, difficulty, learning_objectives, genre_expectations, planning_questions, source_type, visibility, created_by)
values
  ('opinion_essay', 'B1', 'Should Students Have Homework Every Day?', 'Some schools give students homework every single day, while others give much less. In your opinion, should students have daily homework? Give reasons and examples to support your opinion.', 120, 180, 35, array['education','daily life'], 'developing', array['State a clear personal opinion in the introduction','Support an opinion with two or three relevant reasons','Write a conclusion that restates the opinion'], array['A clear thesis statement early in the essay','Simple, clear paragraph structure (one idea per paragraph)','Basic linking words (firstly, also, in conclusion)'], array['What is your opinion — do you agree or disagree with daily homework?','What are two reasons that support your opinion?','Can you think of a personal example or experience?'], 'pasific_library', 'global', null),
  ('opinion_essay', 'B2', 'Is Fame a Positive or Negative Thing for Young People?', 'More and more young people become famous through social media at a very early age. Do you think fame is generally positive or negative for young people? Discuss and give your opinion.', 180, 250, 45, array['social media','youth'], 'standard', array['Develop an opinion with well-supported, specific reasoning','Acknowledge a counter-argument before restating your position','Use a wider range of linking devices'], array['A nuanced opinion, not just a simple yes/no statement','At least one paragraph addressing an opposing view','A conclusion that adds a final, considered thought'], array['What specific risks or benefits does early fame bring?','Can you think of a real or hypothetical example?','What would you say to someone who disagrees with you?'], 'pasific_library', 'global', null),
  ('opinion_essay', 'C1', 'Should Voting Be Mandatory in a Democracy?', 'Some countries require all citizens to vote in elections, while others leave it optional. Do you believe voting should be made mandatory? Argue your position, taking into account the strongest opposing arguments.', 250, 350, 55, array['politics','civic duty'], 'challenging', array['Construct a sophisticated, well-reasoned argument','Engage seriously with the strongest counter-arguments','Use precise, register-appropriate academic vocabulary'], array['A clearly stated, nuanced thesis','Genuine engagement with opposing views, not just a token mention','Cohesive, sophisticated paragraph transitions'], array['What are the strongest arguments for and against mandatory voting?','Does mandatory voting affect the quality or legitimacy of democracy?','What real-world examples (countries) could support your argument?'], 'pasific_library', 'global', null),
  ('argumentative_essay', 'B1', 'Should Mobile Phones Be Allowed in Classrooms?', 'Many schools do not allow students to use mobile phones in class. Do you agree with this rule? Write an essay arguing your position.', 120, 180, 35, array['technology','school rules'], 'developing', array['State and defend a clear position','Support an argument with at least two reasons','Address one opposing point briefly'], array['A clear argumentative stance from the introduction','Logical paragraph order (reason, reason, counter-argument, conclusion)','Simple but accurate linking words'], array['Do you think phones help or distract students in class?','What is one argument against your position, and how would you respond?','What rule (if any) would you suggest instead?'], 'pasific_library', 'global', null),
  ('argumentative_essay', 'B2', 'Should Schools Replace Exams with Continuous Assessment?', 'Some educators argue that final exams should be replaced entirely by continuous assessment throughout the year. Do you agree? Write an argumentative essay presenting your view.', 180, 250, 45, array['education','assessment'], 'standard', array['Build a well-developed argument with specific supporting reasoning','Fairly represent and respond to an opposing viewpoint','Use varied, accurate linking devices'], array['A confident, well-supported thesis','A genuine (not token) counter-argument paragraph','A conclusion that reinforces the argument without merely repeating it'], array['What are the strengths and weaknesses of exams vs. continuous assessment?','Which system is fairer to different types of students, and why?','What would a fair compromise look like?'], 'pasific_library', 'global', null),
  ('argumentative_essay', 'C1', 'Should Companies Be Legally Required to Disclose AI-Generated Content?', 'As AI-generated text, images and video become widespread, some argue companies should be legally required to label such content clearly. Argue for or against mandatory AI-content disclosure laws.', 250, 350, 55, array['technology','law','ethics'], 'challenging', array['Present a sophisticated, well-substantiated legal/ethical argument','Anticipate and rebut the strongest counter-arguments','Use precise, domain-appropriate vocabulary'], array['A sharply defined thesis addressing both practicality and principle','Rigorous engagement with opposing arguments (not dismissal)','Sophisticated cohesive devices throughout'], array['What are the practical challenges of enforcing a disclosure law?','What harms does undisclosed AI content cause, if any?','Is there a middle-ground policy between full disclosure and no regulation?'], 'pasific_library', 'global', null),
  ('for_and_against_essay', 'B1', 'Living in a Flat vs. a House', 'Some people prefer to live in a flat (apartment) while others prefer a house. Write an essay presenting arguments for and against each option, then give your own opinion.', 120, 180, 35, array['housing','lifestyle'], 'developing', array['Present balanced arguments for both sides of an issue','Keep a neutral tone until the concluding opinion','Use simple contrast linkers (but, however)'], array['Roughly equal space given to both sides','Neutral, non-persuasive tone in the main body','A personal opinion only in the conclusion'], array['What is one advantage and one disadvantage of a flat?','What is one advantage and one disadvantage of a house?','Which would you personally choose, and why?'], 'pasific_library', 'global', null),
  ('for_and_against_essay', 'B2', 'Working Remotely vs. Working in an Office', 'Remote work has become far more common in recent years. Write a for-and-against essay examining the arguments on both sides of this debate, followed by your own conclusion.', 180, 250, 45, array['work','technology'], 'standard', array['Develop balanced, well-supported arguments for both sides','Maintain an objective tone throughout the main body','Reach a genuinely considered conclusion, not a simple restatement'], array['Clear, parallel structure across both sides of the argument','A wide range of accurate contrast and addition linkers','A conclusion that weighs the arguments rather than just summarising'], array['What are the productivity and wellbeing arguments on each side?','How might the best answer differ depending on the type of job?','What would a balanced personal conclusion look like?'], 'pasific_library', 'global', null),
  ('for_and_against_essay', 'C1', 'Nuclear Energy as a Solution to Climate Change', 'Some argue nuclear power is essential to solving climate change, while others believe its risks outweigh its benefits. Write a sophisticated for-and-against essay exploring this debate.', 250, 350, 55, array['environment','energy policy'], 'challenging', array['Explore a complex issue with genuine balance and depth','Use precise technical and policy-related vocabulary','Reach a sophisticated, qualified conclusion'], array['Substantive, evidence-aware treatment of both sides','Sophisticated cohesive devices connecting complex ideas','A conclusion that reflects genuine complexity rather than a simple verdict'], array['What specific risks and benefits does nuclear energy present compared to other options?','How do public perception and actual risk differ, if at all?','What conditions might make nuclear energy more or less advisable?'], 'pasific_library', 'global', null),
  ('advantages_disadvantages_essay', 'B1', 'Having a Part-Time Job While Studying', 'Many students choose to work part-time while they study. Write an essay discussing the advantages and disadvantages of this, then give your opinion.', 120, 180, 35, array['work','education'], 'developing', array['Present at least two advantages and two disadvantages','Organise ideas into clear, separate paragraphs','Give a simple, supported final opinion'], array['A clear split between advantages and disadvantages sections','Basic sequencing linkers (firstly, secondly, however)','A conclusion with a personal opinion'], array['What is one clear advantage of working while studying?','What is one clear disadvantage?','What would you recommend to a student considering it?'], 'pasific_library', 'global', null),
  ('advantages_disadvantages_essay', 'B2', 'Studying at a University Abroad', 'An increasing number of students choose to study at universities in other countries. Discuss the advantages and disadvantages of this choice, then give your opinion.', 180, 250, 45, array['education','travel'], 'standard', array['Develop advantages and disadvantages with specific, credible reasoning','Balance the discussion evenly across both sides','Reach a well-justified personal conclusion'], array['Specific, developed points rather than generic statements','A logical, easy-to-follow structure','Appropriate academic register throughout'], array['What personal, academic and financial factors are involved?','What kind of student would benefit most from studying abroad?','What would your own honest opinion be, and why?'], 'pasific_library', 'global', null),
  ('advantages_disadvantages_essay', 'C1', 'Widespread Adoption of Autonomous Vehicles', 'Self-driving cars are advancing rapidly and may soon become common on public roads. Discuss the advantages and disadvantages of widespread autonomous vehicle adoption, then present your own reasoned conclusion.', 250, 350, 55, array['technology','transport','ethics'], 'challenging', array['Analyse a complex socio-technical issue from multiple angles','Support claims with specific, plausible reasoning','Reach a sophisticated conclusion that reflects genuine trade-offs'], array['Rich, specific development of both advantages and disadvantages','Precise technical and ethical vocabulary','A conclusion that avoids oversimplification'], array['What safety, economic and ethical issues are raised by autonomous vehicles?','How might the balance of advantages and disadvantages shift over time?','What conditions would need to be met for safe widespread adoption?'], 'pasific_library', 'global', null),
  ('problem_solution_essay', 'B1', 'Litter in Public Parks', 'Many public parks in cities have a serious litter problem. Write an essay explaining the causes of this problem and suggesting some solutions.', 120, 180, 35, array['environment','community'], 'developing', array['Identify at least two causes of a local problem','Propose realistic, matching solutions','Organise the essay into clear problem and solution sections'], array['A clear separation between problem and solution paragraphs','Solutions that directly address the stated problems','Simple, accurate linking words'], array['Why do you think people leave litter in parks?','What could the city or local community do about it?','What could ordinary visitors do differently?'], 'pasific_library', 'global', null),
  ('problem_solution_essay', 'B2', 'Traffic Congestion in Growing Cities', 'Traffic congestion is a serious problem in many growing cities. Write an essay analysing the main causes of this problem and proposing realistic, well-explained solutions.', 180, 250, 45, array['urban life','transport'], 'standard', array['Analyse causes with specific, well-developed reasoning','Propose solutions that logically address the identified causes','Use a good range of cause-effect and solution linkers'], array['Specific, credible causes rather than vague generalisations','Solutions clearly matched to the causes discussed','A conclusion that evaluates the overall feasibility of the solutions'], array['What are the main causes of traffic congestion in a growing city?','Which solutions have worked in other cities you know of?','What trade-offs might these solutions involve?'], 'pasific_library', 'global', null),
  ('problem_solution_essay', 'C1', 'The Shortage of Affordable Housing in Major Cities', 'Many major cities are facing a severe shortage of affordable housing. Write a sophisticated essay analysing the underlying causes of this crisis and proposing a coherent set of policy solutions.', 250, 350, 55, array['urban policy','economics'], 'challenging', array['Analyse a complex, multi-causal policy issue in depth','Propose a coherent, multi-level policy response','Use precise economic and policy vocabulary'], array['Interrelated causes explored with genuine sophistication','Solutions operating at multiple levels (individual, market, government)','A conclusion that acknowledges the limits of any single solution'], array['What structural, economic and regulatory factors drive housing shortages?','What policies have other cities tried, and how successful were they?','What would a realistic, coordinated solution look like?'], 'pasific_library', 'global', null),
  ('cause_effect_essay', 'B1', 'Why Do Many Teenagers Feel Stressed at School?', 'Many teenagers report feeling stressed because of school. Write an essay explaining the main causes of this stress and its effects on students.', 120, 180, 35, array['education','wellbeing'], 'developing', array['Identify clear causes of a common problem','Describe the resulting effects logically','Use simple cause-effect linking words'], array['Clear separation between causes and effects','Each cause matched to a relevant effect','A conclusion that summarises the overall pattern'], array['What specifically causes stress for teenagers at school?','What effects does this stress have on their daily life?','What could help reduce this stress?'], 'pasific_library', 'global', null),
  ('cause_effect_essay', 'B2', 'The Effects of Fast Fashion on the Environment', 'The fast fashion industry has grown enormously in recent years. Write an essay exploring the main causes behind this growth and its effects on the environment.', 180, 250, 45, array['environment','consumerism'], 'standard', array['Develop causes and effects with specific, credible detail','Use a good range of cause-effect vocabulary and linkers','Maintain an objective, analytical tone throughout'], array['Well-developed, specific causes rather than generalisations','Effects explored with genuine depth (environmental, social, economic)','A conclusion that reflects on the overall significance of the issue'], array['What consumer and industry factors have driven fast fashion''s growth?','What specific environmental effects result from this industry?','Could anything realistically slow this trend?'], 'pasific_library', 'global', null),
  ('cause_effect_essay', 'C1', 'The Causes and Consequences of Brain Drain in Developing Countries', 'Many developing countries lose a significant share of their skilled workers to emigration, a phenomenon known as ''brain drain''. Write a sophisticated essay analysing its causes and its consequences for the countries affected.', 250, 350, 55, array['economics','migration','development'], 'challenging', array['Analyse a complex socioeconomic phenomenon with genuine depth','Distinguish between short-term and long-term consequences','Use precise, discipline-appropriate vocabulary'], array['Multiple interrelated causes explored with sophistication','Consequences considered across economic and social dimensions','A conclusion that reflects the complexity of the issue'], array['What economic and social factors drive skilled emigration?','What are the short-term and long-term consequences for the country of origin?','Are there any policies that meaningfully mitigate brain drain?'], 'pasific_library', 'global', null),
  ('compare_contrast_essay', 'B1', 'Studying in the Morning vs. Studying at Night', 'Some students prefer studying early in the morning, while others prefer studying late at night. Write an essay comparing these two study habits.', 120, 180, 35, array['education','habits'], 'developing', array['Compare two options point by point','Use simple comparison and contrast language','Reach a simple personal conclusion'], array['Clear, parallel treatment of both options','Basic comparison linkers (similarly, on the other hand)','A short concluding opinion'], array['What is one benefit of studying in the morning?','What is one benefit of studying at night?','Which do you personally prefer, and why?'], 'pasific_library', 'global', null),
  ('compare_contrast_essay', 'B2', 'Traditional Classrooms vs. Online Learning Platforms', 'Both traditional classroom teaching and online learning platforms are widely used today. Write an essay comparing and contrasting these two approaches to education.', 180, 250, 45, array['education','technology'], 'standard', array['Compare two options using consistent, explicit criteria','Use a wide range of comparison and contrast structures','Reach a nuanced conclusion rather than simply favouring one option'], array['Explicit, consistent points of comparison across the essay','A clear point-by-point or block structure','A conclusion that reflects genuine trade-offs between the two'], array['What criteria will you use to compare the two (cost, flexibility, engagement, etc.)?','In what situations might each option be better suited?','Could the two approaches be combined effectively?'], 'pasific_library', 'global', null),
  ('compare_contrast_essay', 'C1', 'Two Economic Approaches to Reducing Unemployment', 'Governments often choose between direct job-creation programmes and incentives for private-sector hiring to reduce unemployment. Write a sophisticated essay comparing and contrasting these two approaches.', 250, 350, 55, array['economics','public policy'], 'challenging', array['Compare complex policy approaches using well-defined criteria','Use precise economic and policy vocabulary','Reach a sophisticated, context-sensitive conclusion'], array['Systematic comparison across multiple, explicit dimensions','Sophisticated cohesive devices linking complex ideas','A conclusion that avoids treating either approach as universally superior'], array['What are the intended mechanisms and risks of each approach?','Under what economic conditions might one approach outperform the other?','Could a combined or sequenced strategy work better than either alone?'], 'pasific_library', 'global', null),
  ('formal_email', 'B1', 'Enquiring About a Language Course', 'Write a formal email to a language school asking about their English courses. Ask about course levels, schedule, and price.', 80, 120, 25, array['education','enquiry'], 'developing', array['Use an appropriate formal greeting and closing','Ask clear, specific questions','Maintain a polite, formal register throughout'], array['Correct formal opening (Dear Sir/Madam) and matching closing (Yours faithfully)','Short, clear paragraphs with one purpose each','No informal contractions or slang'], array['What exactly do you want to know about the course?','How will you politely introduce your request?','How will you close the email appropriately?'], 'pasific_library', 'global', null),
  ('formal_email', 'B2', 'Requesting a Reference for a Part-Time Job', 'Write a formal email to a former teacher or employer asking them to provide a reference for a part-time job application. Explain the job and why you are asking them specifically.', 120, 180, 30, array['work','education'], 'standard', array['Make a polite, well-justified request','Provide relevant context without over-explaining','Use an appropriately formal but warm register'], array['A clear, specific request stated early','Relevant supporting context (why this person, why this job)','A polite closing that makes it easy for the recipient to respond'], array['Why are you asking this specific person for a reference?','What details would help them write a strong reference?','What is the deadline, and how will you mention it politely?'], 'pasific_library', 'global', null),
  ('formal_email', 'C1', 'Proposing a Partnership Between Your School and a Local Business', 'Write a formal email to a local business proposing a partnership or sponsorship with your school (for example, for an event, an internship programme, or equipment donation). Make a persuasive but professional case.', 180, 250, 40, array['business','education'], 'challenging', array['Construct a persuasive but professional proposal','Anticipate and address likely practical questions','Use sophisticated, precisely calibrated formal register'], array['A clear, compelling case for mutual benefit','Specific, credible details supporting the proposal','A professional closing proposing a concrete next step'], array['What specific benefit would the partnership offer the business?','What concerns might the business have, and how would you address them?','What is the specific next step you want them to take?'], 'pasific_library', 'global', null),
  ('informal_email', 'B1', 'Telling a Friend About Your New School', 'Write an informal email to a friend telling them about your new school. Describe what it''s like and how you feel about it.', 80, 120, 25, array['daily life','school'], 'developing', array['Use an appropriately casual, friendly tone','Describe personal experience with relevant detail','Use simple informal email conventions'], array['Informal greeting and closing (Hi.../See you soon)','Natural, everyday vocabulary and contractions','A friendly, conversational structure'], array['What is the most interesting or surprising thing about your new school?','How do you feel about it so far?','What would you like to ask your friend in return?'], 'pasific_library', 'global', null),
  ('informal_email', 'B2', 'Inviting a Friend to Visit Your Country', 'Write an informal email inviting a friend to visit your country. Suggest things to do and explain why you think they would enjoy it.', 120, 180, 30, array['travel','friendship'], 'standard', array['Write persuasively while keeping a natural, friendly tone','Organise suggestions in an engaging, readable way','Use a good range of informal, natural vocabulary'], array['A genuinely conversational, natural voice throughout','Specific, appealing suggestions rather than generic ones','A warm, natural closing that invites a reply'], array['What specific places or experiences would most appeal to your friend?','Why do you think they, personally, would enjoy visiting?','What practical details might they want to know (timing, cost, etc.)?'], 'pasific_library', 'global', null),
  ('informal_email', 'C1', 'Persuading a Friend to Change Their Career Plans', 'A close friend has told you about a career decision you think may not be right for them. Write an informal email giving them honest, thoughtful advice.', 180, 250, 35, array['friendship','career'], 'challenging', array['Give honest, specific advice while maintaining warmth and support','Balance directness with genuine empathy','Use sophisticated but naturally conversational language'], array['A natural, warm register despite the sensitive content','Honest, specific reasoning rather than vague reassurance','A supportive close that leaves the decision with the friend'], array['What exactly concerns you about your friend''s plan?','How can you raise this honestly without sounding critical?','What would genuinely helpful, actionable advice look like?'], 'pasific_library', 'global', null),
  ('complaint_letter', 'B1', 'A Faulty Online Order', 'You recently received a faulty item from an online shop. Write a formal letter of complaint explaining the problem and what you want the company to do.', 100, 150, 30, array['consumer rights','shopping'], 'developing', array['Clearly describe a problem with relevant detail','State a specific, reasonable desired outcome','Use appropriate formal complaint letter conventions'], array['Correct formal opening and closing','A clear description of the fault','A specific request (refund, replacement, etc.)'], array['What exactly is wrong with the item?','What do you want the company to do about it?','How will you keep the tone firm but polite?'], 'pasific_library', 'global', null),
  ('complaint_letter', 'B2', 'Poor Service at a Gym', 'You have had a disappointing experience with the customer service at your gym. Write a formal letter of complaint describing what happened and what you expect the gym to do.', 150, 220, 35, array['consumer rights','services'], 'standard', array['Present a credible, well-sequenced account of events','Maintain a firm but professional tone throughout','Make a clear, reasonable request for resolution'], array['A clear chronological account of what went wrong','Appropriately firm but not aggressive language','A specific, actionable request for resolution or compensation'], array['What specific incidents will you describe, in what order?','How has this affected you (inconvenience, cost, etc.)?','What outcome would you consider a fair resolution?'], 'pasific_library', 'global', null),
  ('complaint_letter', 'C1', 'A Serious Data Privacy Breach by a Company', 'A company you are a customer of has suffered a data breach that exposed your personal information. Write a formal, sophisticated letter of complaint demanding an explanation and appropriate remedial action.', 220, 300, 45, array['consumer rights','privacy','technology'], 'challenging', array['Construct a precisely evidenced, professionally forceful complaint','Reference relevant obligations or expectations explicitly','Make specific, well-justified demands'], array['Precise, professional language throughout despite the serious tone','Specific, well-justified demands (explanation, remedial steps, compensation)','A closing that sets clear expectations for response'], array['What specific information was exposed, and what risk does this pose to you?','What explanation and remedial steps are you entitled to expect?','What will you do if the company does not respond adequately?'], 'pasific_library', 'global', null),
  ('application_letter', 'B1', 'Applying to Volunteer at a Local Animal Shelter', 'Write a letter applying to volunteer at a local animal shelter. Explain why you want to volunteer and what skills or qualities you can offer.', 100, 150, 30, array['volunteering','community'], 'developing', array['State a clear purpose and relevant motivation','Mention relevant personal qualities or availability','Use correct formal letter conventions'], array['Clear statement of purpose in the opening','Relevant personal detail supporting the application','Correct formal opening and closing'], array['Why do you want to volunteer at this shelter specifically?','What relevant qualities or experience can you mention?','When are you available to help?'], 'pasific_library', 'global', null),
  ('application_letter', 'B2', 'Applying for a Student Exchange Programme', 'Write a letter applying for a student exchange programme abroad. Explain your motivation, relevant experience, and what you hope to gain from the experience.', 150, 220, 35, array['education','travel'], 'standard', array['Present specific, credible motivation and qualifications','Connect personal goals to the specific programme','Maintain an appropriately formal, confident register'], array['Specific, well-supported reasons for applying','Relevant prior experience or qualities clearly presented','A confident but appropriately humble closing'], array['Why does this specific programme or country interest you?','What relevant experience or qualities make you a good candidate?','What do you hope to gain, personally and academically?'], 'pasific_library', 'global', null),
  ('application_letter', 'C1', 'Applying for a Competitive Research Internship', 'Write a sophisticated letter applying for a highly competitive research internship. Explain your relevant background, your specific interest in this research area, and why you would be a strong fit for the programme.', 220, 300, 45, array['academia','career'], 'challenging', array['Present highly specific, credible evidence of suitability','Connect personal background precisely to the programme''s specific focus','Use sophisticated, professional register throughout'], array['Precise, specific evidence rather than generic claims of suitability','Genuine, specific engagement with the programme''s particular focus','A confident, professional closing appropriate to a competitive application'], array['What specific experience or coursework makes you a strong candidate?','What about this particular research area or team genuinely interests you?','How will you demonstrate genuine research engagement rather than generic enthusiasm?'], 'pasific_library', 'global', null),
  ('article', 'B1', 'My Favourite Season and Why', 'Write an article for your school magazine about your favourite season of the year. Explain why you like it and what you enjoy doing during that time.', 120, 180, 35, array['daily life','seasons'], 'developing', array['Write in an engaging, personal style suited to a magazine','Organise ideas clearly around a simple structure','Address the reader directly where appropriate'], array['An engaging title and opening','A friendly, personal tone throughout','A short concluding thought or recommendation'], array['What is your favourite season, and why?','What specific activities or memories do you associate with it?','How will you make your opening interesting for readers?'], 'pasific_library', 'global', null),
  ('article', 'B2', 'The Growing Popularity of Home Workouts', 'Write an article for a lifestyle website exploring why home workouts have become so popular in recent years. Discuss the reasons and give your own view on the trend.', 180, 250, 45, array['health','lifestyle','trends'], 'standard', array['Explore a trend with engaging, well-organised reasoning','Use a lively, reader-friendly magazine style','Include a clear personal perspective on the trend'], array['A catchy, genre-appropriate headline','Vivid, engaging language suited to a lifestyle publication','A clear final take on the trend, not just a summary'], array['What specific factors have driven this trend?','What are the genuine benefits and limitations of home workouts?','What is your own honest view on the trend?'], 'pasific_library', 'global', null),
  ('article', 'C1', 'Why Slow Travel Is Reshaping Tourism', 'Write a sophisticated article for a travel and culture magazine exploring the ''slow travel'' movement and why it is reshaping how people think about tourism. Offer genuine insight, not just a description of the trend.', 250, 350, 55, array['travel','culture','trends'], 'challenging', array['Write with genuine stylistic flair appropriate to quality magazine writing','Develop an original angle or insight, not just a summary','Use precise, vivid, sophisticated vocabulary'], array['A distinctive, confident authorial voice','A genuinely original insight or argument about the trend','A memorable, well-crafted closing line'], array['What specifically distinguishes slow travel from conventional tourism?','What deeper cultural or economic shift might explain its rise?','What original angle or insight can you bring beyond a simple description?'], 'pasific_library', 'global', null),
  ('report', 'B1', 'Survey on Students'' Free-Time Activities', 'Write a report presenting the results of a survey about how students in your class spend their free time. Include findings and one or two simple recommendations.', 120, 180, 35, array['school','survey'], 'developing', array['Present survey findings clearly using headings','Draw a simple, logical recommendation from the findings','Use an appropriately objective, neutral tone'], array['Clear headings (Introduction, Findings, Recommendations)','An objective, factual tone throughout','Recommendations that logically follow from the findings'], array['What were the main patterns in the survey results?','What is one clear, useful recommendation based on these findings?','How will you organise your report with headings?'], 'pasific_library', 'global', null),
  ('report', 'B2', 'Evaluating the School Cafeteria''s Menu Options', 'Write a report evaluating the food options in your school cafeteria based on student feedback. Present the findings clearly and recommend specific improvements.', 180, 250, 40, array['school','food'], 'standard', array['Present findings with specific, credible supporting detail','Draw recommendations that clearly follow from the findings','Maintain a professional, objective report register'], array['Clear section headings organising findings and recommendations','Specific, credible supporting detail (not vague generalisations)','Recommendations directly tied to the findings presented'], array['What specific issues or preferences did the feedback reveal?','What realistic improvements would address these issues?','How will you structure the report for clarity?'], 'pasific_library', 'global', null),
  ('report', 'C1', 'Assessing the Feasibility of a Four-Day School Week', 'Write a sophisticated feasibility report assessing whether your school should move to a four-day school week. Present evidence, weigh genuine risks and benefits, and offer a clear, well-justified recommendation.', 250, 350, 55, array['education','policy'], 'challenging', array['Present a balanced, evidence-based feasibility analysis','Weigh genuine risks against benefits rather than only advocating one side','Offer a specific, well-justified, actionable recommendation'], array['Genuinely balanced treatment of both benefits and risks','Precise, professional report register throughout','A specific, actionable recommendation, potentially including a pilot or trial'], array['What are the genuine academic and logistical risks of this change?','What benefits would need to be demonstrated to justify it?','What would a sensible, cautious path to implementation look like?'], 'pasific_library', 'global', null),
  ('review', 'B1', 'A Local Café You Recently Visited', 'Write a review of a local café or restaurant you visited recently. Describe the food, service and atmosphere, and say whether you would recommend it.', 100, 150, 30, array['food','local life'], 'developing', array['Describe an experience with relevant specific detail','Give a balanced view including at least one positive and one negative point','End with a clear recommendation'], array['Coverage of food, service and atmosphere','A balanced view, not only positive or only negative','A clear final recommendation'], array['What did you like most about the café?','Was there anything you didn''t like?','Would you recommend it, and to whom?'], 'pasific_library', 'global', null),
  ('review', 'B2', 'A Recently Released Film', 'Write a review of a film you have watched recently. Discuss the plot, acting and overall quality, and give your honest opinion with a clear recommendation.', 150, 220, 35, array['entertainment','film'], 'standard', array['Evaluate a work critically with balanced, specific reasoning','Use appropriate genre-specific critical vocabulary','Give clear guidance for different types of viewer'], array['Balanced evaluation covering multiple aspects (plot, acting, style)','Specific evidence supporting each judgement, not vague praise or criticism','Clear guidance on who would or wouldn''t enjoy it'], array['What specifically worked well, and what didn''t?','What kind of viewer would most enjoy this film?','What is your overall verdict, and how confident are you in it?'], 'pasific_library', 'global', null),
  ('review', 'C1', 'A Critically Acclaimed Novel', 'Write a sophisticated review of a novel that has received significant critical acclaim. Offer a genuinely critical evaluation, going beyond a plot summary to assess its themes, style and impact.', 220, 300, 45, array['literature','culture'], 'challenging', array['Move beyond plot summary into genuine critical analysis','Evaluate themes and stylistic choices with specific evidence','Write with a confident, distinctive critical voice'], array['Genuine critical depth rather than a plot summary','Specific textual evidence supporting evaluative claims','A distinctive, confident critical voice throughout'], array['What themes or stylistic choices most interest you critically?','Does the acclaim seem justified, in your view — why or why not?','What specific evidence best supports your critical judgement?'], 'pasific_library', 'global', null),
  ('narrative_story', 'B1', 'A Day That Didn''t Go as Planned', 'Write a story about a day that didn''t go the way you expected. Say what happened and how you felt.', 120, 180, 35, array['personal experience','daily life'], 'developing', array['Tell a story with a clear beginning, middle and end','Use past tenses accurately and consistently','Include some description of feelings or reactions'], array['Clear chronological structure','Accurate, consistent use of past tenses','A satisfying ending or reflection'], array['What was supposed to happen that day?','What actually happened instead?','How did you feel by the end of the day?'], 'pasific_library', 'global', null),
  ('narrative_story', 'B2', 'A Surprising Encounter While Travelling', 'Write a story about a surprising or memorable encounter you had while travelling. Build tension or interest before revealing what happened.', 180, 250, 40, array['travel','personal experience'], 'standard', array['Build narrative tension or interest before a key moment','Use a good range of descriptive and narrative vocabulary','Vary sentence structure for narrative effect'], array['A clear narrative arc with a build-up and a turning point','Vivid, specific sensory or emotional detail','Natural, varied narrative pacing'], array['What made this encounter surprising or memorable?','How will you build interest before revealing the key moment?','What sensory or emotional detail could bring the scene to life?'], 'pasific_library', 'global', null),
  ('narrative_story', 'C1', 'A Decision That Changed Everything', 'Write a sophisticated short story about a decision — yours or a character''s — that changed everything that followed. Use narrative technique to convey the emotional weight of the decision without over-explaining it.', 250, 350, 55, array['personal experience','reflection'], 'challenging', array['Convey emotional depth through implication rather than direct statement','Use sophisticated narrative techniques (e.g. non-linear structure, controlled pacing)','Write with a distinctive, controlled prose style'], array['Emotional content conveyed through detail and implication, not exposition','Sophisticated control of pacing and structure','A distinctive, controlled narrative voice throughout'], array['What was the decision, and what made it significant?','How can you show its emotional weight without stating it directly?','What structure (linear, flashback, etc.) would best serve this story?'], 'pasific_library', 'global', null),
  ('descriptive_writing', 'B1', 'Describe Your Favourite Place at Home', 'Write a description of your favourite place in your home. Use your senses to describe what it looks, sounds and feels like.', 120, 180, 35, array['daily life','home'], 'developing', array['Use sensory detail (sight, sound, touch) in description','Organise description using clear spatial order','Connect the description to a personal feeling'], array['Clear spatial organisation guiding the reader through the space','At least two different senses used in the description','A personal reflection connecting the place to a feeling'], array['What does this place look like in detail?','What sounds or textures are part of this place?','Why is this place special to you?'], 'pasific_library', 'global', null),
  ('descriptive_writing', 'B2', 'Describe a Busy Street Market', 'Write a vivid description of a busy street market, real or imagined. Use rich sensory detail to bring the scene to life for the reader.', 180, 250, 40, array['places','culture'], 'standard', array['Use varied, precise sensory vocabulary across multiple senses','Create atmosphere through careful word choice','Organise description for maximum vividness and flow'], array['Rich, precise sensory vocabulary across sight, sound and smell','A clear sense of atmosphere and movement in the scene','Natural, varied sentence structure suited to description'], array['What specific sights, sounds and smells define this market?','How can you convey the movement and energy of the scene?','What single impression do you want the reader to be left with?'], 'pasific_library', 'global', null),
  ('descriptive_writing', 'C1', 'Describe an Abandoned Building', 'Write a sophisticated, atmospheric description of an abandoned building. Use precise sensory detail and figurative language to evoke a specific mood, and consider what meaning or reflection the description might offer beyond the physical scene.', 250, 350, 55, array['places','atmosphere','reflection'], 'challenging', array['Use figurative language with precision and control','Evoke a specific, sustained mood or atmosphere','Elevate description into genuine reflective meaning'], array['Precise, controlled figurative language throughout','A sustained, coherent mood or atmosphere','A closing that moves beyond physical description into reflection'], array['What specific sensory details best convey the building''s history?','What mood or atmosphere do you want to create, and how?','What deeper meaning or reflection might the scene suggest?'], 'pasific_library', 'global', null),
  ('blog_post', 'B1', 'Three Things I Learned This Year', 'Write a blog post sharing three things you have learned this year, personally or academically. Explain why each one matters to you.', 120, 180, 35, array['personal growth','reflection'], 'developing', array['Write in an engaging, personal blog style','Organise ideas clearly using a numbered or listed structure','Explain personal significance simply but clearly'], array['A friendly, direct address to the reader','Clear organisation (e.g. a numbered list)','A short, warm closing'], array['What is one thing you learned this year, and why does it matter?','What are two other lessons you could include?','How will you end the post in a friendly way?'], 'pasific_library', 'global', null),
  ('blog_post', 'B2', 'Why I Started Journaling', 'Write a blog post explaining why you started journaling (or another habit) and what effect it has had on you. Be honest about both the benefits and the challenges.', 180, 250, 40, array['personal growth','habits'], 'standard', array['Write an honest, balanced personal account','Use a natural, conversational blog voice','Reflect genuinely rather than only listing benefits'], array['A natural, conversational voice throughout','Honest acknowledgement of both benefits and difficulties','A genuine, reflective closing rather than a generic conclusion'], array['What prompted you to start this habit?','What has genuinely been difficult about maintaining it?','What would you honestly say to someone considering trying it?'], 'pasific_library', 'global', null),
  ('blog_post', 'C1', 'What a Digital Detox Actually Taught Me', 'Write a sophisticated, reflective blog post about a period of reduced technology or social media use (real or imagined). Go beyond the obvious lessons to explore what the experience revealed about your habits or values.', 250, 350, 50, array['personal growth','technology','reflection'], 'challenging', array['Move beyond generic conclusions into genuine, specific reflection','Write with a distinctive, natural but sophisticated voice','Balance honesty about difficulty with genuine insight'], array['Genuine, specific reflection rather than generic ''lessons learned''','A natural yet sophisticated blog voice throughout','An honest account that avoids an overly neat, tidy conclusion'], array['What specifically surprised you during this experience?','What did it reveal about your habits, values or relationships?','How can you avoid a neat, generic conclusion in favour of something more honest?'], 'pasific_library', 'global', null);